import sympy as sp
r1,r2,f0,f3,sg,d0,d3,z1,z2,z3,z4,z5=sp.symbols("r1 r2 f0 f3 sg d0 d3 z1 z2 z3 z4 z5")
SUBS={r1:-1,r2:-1,f0:2,f3:2}
PAR=[]
BS=[]
E={(0,0):"1",(0,1):"1",(0,2):"1",(0,3):"1",(0,4):"1",(1,0):"1+z1*(1)+z2*((-f0/2))+z3*((-0/2))+z4*((-0/2))+z5*((-f3/2))",(1,1):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(1,2):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(1,3):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(1,4):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(2,0):"1+z1*(-1)+z2*((-f0/2))+z3*((-0/2))+z4*((-0/2))+z5*((-f3/2))",(2,1):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(2,2):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(2,3):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(2,4):"1+z1*(0)+z2*(0)+z3*(0)+z4*(0)+z5*(0)",(3,0):"1+z1*(0)+z2*((-4))+z3*((-0))+z4*((-0))+z5*((-0))",(3,1):"1+z1*(0)+z2*(1)+z3*(0)+z4*(0)+z5*((-r1*(3+r1+r2)+(1+r1)*(r1+r2-1)))",(3,2):"1+z1*(0)+z2*(1)+z3*(0)+z4*(0)+z5*((-r2*(3+r1+r2)+(1+r2)*(r1+r2-1)))",(3,3):"1+z1*(0)+z2*(1)+z3*(0)+z4*(0)+z5*((3+r1+r2))",(3,4):"1+z1*(0)+z2*(1)+z3*(0)+z4*(0)+z5*((r1+r2-1))",(4,0):"1+z1*(0)+z2*(f0)+z3*(0)+z4*(0)+z5*(f3)",(4,1):"1+z1*(0)+z2*(0)+z3*(1)+z4*(0)+z5*(0)",(4,2):"1+z1*(0)+z2*(0)+z3*(0)+z4*(1)+z5*(0)",(4,3):"1+z1*(0)+z2*(0)+z3*(r1)+z4*(r2)+z5*(0)",(4,4):"1+z1*(0)+z2*(0)+z3*((-1-r1))+z4*((-1-r2))+z5*(0)"}
for k,z in enumerate([z1,z2,z3,z4,z5]):
    M=sp.zeros(5,5)
    for (i,j),e in E.items():
        ex=sp.sympify(e.replace("^","**"),locals=dict(r1=r1,r2=r2,f0=f0,f3=f3,sg=sg,d0=d0,d3=d3,z1=z1,z2=z2,z3=z3,z4=z4,z5=z5))
        M[i,j]=sp.expand(sp.diff(ex,z).subs(SUBS))
    BS.append(M)
